from collections import deque
seen=set(); comps=[]
for r in range(16):
  for c in range(16):
    if grid[r][c] != 7 and (r,c) not in seen:
      q=deque([(r,c)]); seen.add((r,c)); cells=[]
      while q:
        x,y=q.popleft(); cells.append((x,y))
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
          xx,yy=x+dx,y+dy
          if 0<=xx<16 and 0<=yy<16 and grid[xx][yy]!=7 and (xx,yy) not in seen:
            seen.add((xx,yy)); q.append((xx,yy))
      rs=[x for x,y in cells]; cs=[y for x,y in cells]
      vals={grid[x][y] for x,y in cells if grid[x][y] not in (0,7)}
      comps.append((min(rs),max(rs),min(cs),max(cs),len(cells),vals))
comps

out=[row.copy() for row in grid]
for r0,r1,c0,c1 in [(0,7,11,14),(3,10,6,9),(12,14,1,5)]:
  for r in range(r0,r1+1):
    for c in range(c0,c1+1): out[r][c]=7
import json
print(json.dumps(out))
